import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"2013年 · 押注美国未来","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2013年.md","filePath":"05_quotes/by-year/2013年.md"}'),r={name:"05_quotes/by-year/2013年.md"};function s(c,e,u,h,_,q){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2013年-·-押注美国未来" tabindex="-1">2013年 · 押注美国未来 <a class="header-anchor" href="#_2013年-·-押注美国未来" aria-label="Permalink to &quot;2013年 · 押注美国未来&quot;">​</a></h1><blockquote><p>查理和我一直认为押注美国不断上升的繁荣是非常接近确定的事。事实上，在过去237年里，谁曾因押注美国衰落而获益？——巴菲特（83岁）</p></blockquote><p>本页收录2013年致股东信中的经典语录。本年以完成亨氏收购、延续五大支柱增长为主线，并包含巴菲特最具影响力的投资哲学论述。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>你不需要成为专家才能获得满意的投资回报。但如果你不是，你必须认识到自己的局限性，遵循一条肯定能相当好地运作的路线。保持简单，不要好高骛远。</p></blockquote><blockquote><p>关注你正在考虑的资产的未来生产力。如果你对粗略估计该资产的未来利润感到不舒服，就忘记它继续前进。</p></blockquote><blockquote><p>如果你对预期价格变化感兴趣，你就是在投机。这并无不当。然而，我知道我无法成功投机，我对那些声称持续成功这样做的人持怀疑态度。</p></blockquote><blockquote><p>投资时恐惧气氛是你的朋友；亢奋世界是你的敌人。</p></blockquote><blockquote><p>比赛由专注于球场的球员赢得——而不是那些眼睛盯着记分牌的人。如果你能在周六和周日不看股价，试着在工作日也这样做。</p></blockquote><blockquote><p>非专业人士的目标不应是挑选赢家——他和他的&quot;帮手&quot;都做不到——而应该是拥有一个总体注定表现良好的企业横截面。低成本标普500指数基金将实现这一目标。</p></blockquote><blockquote><p>价格是你支付的，价值是你得到的。</p></blockquote><blockquote><p>我们在伯克希尔更愿意持有一家优秀公司的可观但非控股股份，也不愿意100%持有一家平庸企业；拥有希望钻石的部分权益胜过拥有全部的人造钻石。</p></blockquote><blockquote><p>从长远来看，坏消息是投资者的好朋友——它能让你以折扣价购买美国的一部分未来。</p></blockquote><blockquote><p>查理和我希望能通过各种途径提升伯克希尔的每股内在价值：(1)持续改善我们众多子公司的基本盈利能力；(2)通过补强型收购进一步提高其利润；(3)从我们投资对象的增长中受益；(4)在伯克希尔股票以显著低于内在价值的折扣价可得时回购；(5)偶尔进行大型收购。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2013年伯克希尔每股账面价值增长18.2%，但跑输标普500的32.4%。全年完成两笔大型收购——亨氏（与3G资本合作）和NV Energy，五大支柱业务合计税前利润创纪录达108亿美元。本年信件后半部分包含巴菲特关于农场和纽约房地产两笔投资的经典论述，系统阐述了投资的核心原则。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2013年-翻译-·-01-letters-2013年-核心总结-·-01-letters-2013年-思维导图" tabindex="-1"><a href="/01_letters/2013年/翻译.html">01_letters/2013年/翻译</a> · <a href="/01_letters/2013年/核心总结.html">01_letters/2013年/核心总结</a> · <a href="/01_letters/2013年/思维导图.html">01_letters/2013年/思维导图</a> <a class="header-anchor" href="#_01-letters-2013年-翻译-·-01-letters-2013年-核心总结-·-01-letters-2013年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2013年/翻译]] · [[→ 核心总结|01_letters/2013年/核心总结]] · [[→ 思维导图|01_letters/2013年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2013年/翻译.html">/01_letters/2013年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{i as __pageData,p as default};
